```javascript
// Importez Discord.js et enregistrez le client
const { Client, GatewayIntentBits, SlashCommandBuilder } = require('discord.js');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent,
  ],
});

// Connexion du client au serveur Discord
client.on('ready', () => {
  console.log(`Bot ${client.user.tag} est prêt!`);
});

// Commande "bannir" en tant que commande slash
const data = new SlashCommandBuilder()
  .setName('bannir')
  .setDescription('Bannir un membre du serveur.')
  .addUserOption(option =>
    option
      .setName('membre')
      .setDescription('Le membre à bannir.')
      .setRequired(true)
  )
  .toJSON();

// Écouteur d'événements de commande
client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const { commandName, options } = interaction;

  if (commandName === 'bannir') {
    const member = options.getUser('membre');

    // Vérifiez si le membre à bannir est dans le serveur
    if (!member || !interaction.guild.members.cache.has(member.id)) {
      return interaction.reply({ content: 'Le membre à bannir n\'est pas dans le serveur.', ephemeral: true });
    }

    // Bannir le membre
    try {
      await interaction.member.ban({ days: 7 });
      return interaction.reply({ content: `${member.user.tag} a été banni.` });
    } catch (error) {
      console.error(error);
      return interaction.reply({ content: 'Une erreur est survenue lors du bannissement du membre.', ephemeral: true });
